function normalizeProxySettings(proxy) {
  let { server, bypass } = proxy;
  let url3;
  try {
    url3 = new URL(server);
    if (!url3.host || !url3.protocol)
      url3 = new URL("http://" + server);
  } catch (e) {
    url3 = new URL("http://" + server);
  }
  if (url3.protocol === "socks4:" && (proxy.username || proxy.password))
    throw new Error(`Socks4 proxy protocol does not support authentication`);
  if (url3.protocol === "socks5:" && (proxy.username || proxy.password))
    throw new Error(`Browser does not support socks5 proxy authentication`);
  server = url3.protocol + "//" + url3.host;
  if (bypass)
    bypass = bypass.split(",").map((t) => t.trim()).join(",");
  return { ...proxy, server, bypass };
}
